vec3 mandel(vec2 uv) {
    vec2 c = uv;
    vec2 z = vec2(0.0);
    int MAX_N = 300;
    int n = -1;
    float temp = 0.0;
    while (++n < MAX_N) {
        float t1 = z.x * z.x;
        float t2 = z.y * z.y;
        temp = t1 + t2;
        if (temp > 4.0) break;
        z = vec2(t1 - t2, 2.0 * z.x * z.y) + c;        
    }

    if (temp >= 4.0) {
        float col = float(n) / 100.0;
        return vec3(1.0 - sin(col * 2.8),
                    1.0 - sin(col * 6.4 + 0.4),
                    1.0 - sin(col * 12.9 + 0.8));

    }
    return vec3(0.0);
}

vec3 mandelFragCoord(vec2 fragCoord) {
	vec2 uv = 2.0 * fragCoord.xy / iResolution.xy - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    uv /= pow(2.0, (0.5 + 0.5 * sin(iTime / 10.0 - 3.14 / 2.0)) * 18.0);
    uv += vec2(0.37, 0.1);

    return mandel(uv);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 col = mandelFragCoord(fragCoord);
    col += mandelFragCoord(fragCoord + vec2(0.5, 0.0));
    col += mandelFragCoord(fragCoord + vec2(0.0, -0.5));
    col += mandelFragCoord(fragCoord + vec2(0.5, -0.5));
    col /= 4.0;

    fragColor = vec4(col, 0.0);    
}
